function renderManagementReport(){const select=$('#reportClientFilter');if(!select)return;const current=select.value;select.innerHTML='<option value="">Todos os clientes</option>'+db.clients.map(c=>`<option value="${esc(c.id)}">ID ${esc(c.publicId||'—')} · ${esc(c.name)}</option>`).join('');if(db.clients.some(c=>c.id===current))select.value=current;const rows=managementReportRows(),income=rows.reduce((n,x)=>n+(x.cashDirection==='entrada'?(Number(x.paidAmount)||0):0),0),expenses=rows.reduce((n,x)=>n+(x.cashDirection==='saida'?(Number(x.paidAmount)||0):0),0),pendingIn=rows.reduce((n,x)=>n+(x.cashDirection==='entrada'?(Number(x.pendingAmount)||0):0),0),pendingOut=rows.reduce((n,x)=>n+(x.cashDirection==='saida'?(Number(x.pendingAmount)||0):0),0);$('#managementReportCount').textContent=rows.length;$('#managementReportOsCount').textContent=rows.filter(x=>x.type==='os').length;$('#managementReportQuoteCount').textContent=rows.filter(x=>x.type==='orcamento').length;$('#managementReportIncome').textContent=fmt(income);$('#managementReportExpenses').textContent=fmt(expenses);$('#managementReportProfit').textContent=fmt(income-expenses);$('#managementReportPending').textContent='A receber '+fmt(pendingIn)+' · A pagar '+fmt(pendingOut);$('#managementReportCaption').textContent=`${rows.length} ${rows.length===1?'registro':'registros'} · receitas e despesas consideram somente pagamentos realizados; propostas e OS ficam fora do lucro líquido.`;$('#managementReportRows').innerHTML=rows.map(x=>`<tr><td>${dateText(x.date)}</td><td>${esc(x.typeLabel)}</td><td>${esc(x.clientName||'—')}<small class="report-client-id">${x.clientPublicId?`ID ${esc(x.clientPublicId)}`:''}</small></td><td>${esc(x.title)}</td><td><span class="report-status-tag ${esc(x.status)}">${esc(x.statusLabel)}</span></td><td>${fmt(x.amount)}</td></tr>`).join('');$('#managementReportEmpty').hidden=rows.length>0}
