function printManagementReport(){const rows=managementReportRows(),income=rows.reduce((n,x)=>n+(x.cashDirection==='entrada'?(Number(x.paidAmount)||0):0),0),expenses=rows.reduce((n,x)=>n+(x.cashDirection==='saida'?(Number(x.paidAmount)||0):0),0),pendingIn=rows.reduce((n,x)=>n+(x.cashDirection==='entrada'?(Number(x.pendingAmount)||0):0),0),pendingOut=rows.reduce((n,x)=>n+(x.cashDirection==='saida'?(Number(x.pendingAmount)||0):0),0),view=document.createElement('div');view.id='managementReportPrint';view.innerHTML=`<header><img src="santory-logo.png" alt="SantoryTec"><div><h1>Relatório gerencial</h1><p>${esc(reportFilterDescription())}</p><small>Gerado em ${new Date().toLocaleString('pt-BR')}</small></div></header><div class="report-print-total">${rows.length} registros · Recebido: ${fmt(income)} · Pago: ${fmt(expenses)} · Saldo líquido: ${fmt(income-expenses)} · A receber / pagar: ${fmt(pendingIn)} / ${fmt(pendingOut)}</div><table><thead><tr><th>Data</th><th>Tipo</th><th>Cliente / ID</th><th>Registro</th><th>Status</th><th>Valor</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${dateText(x.date)}</td><td>${esc(x.typeLabel)}</td><td>${esc(x.clientName||'—')}<small>${x.clientPublicId?`ID ${esc(x.clientPublicId)}`:''}</small></td><td>${esc(x.title)}</td><td>${esc(x.statusLabel)}</td><td>${fmt(x.amount)}</td></tr>`).join('')}</tbody></table><footer>Santory Tec · Relatório gerencial</footer>`;document.body.append(view);document.body.classList.add('management-report-printing');const cleanup=()=>{document.body.classList.remove('management-report-printing');view.remove()};window.addEventListener('afterprint',cleanup,{once:true});window.print();setTimeout(cleanup,60000)}
