  if(!confirm('Mesclar o backup com os dados atuais? Registros novos serão adicionados; os atuais serão preservados.'))return;
  const next={...db};for(const name of Object.keys(aliases)){const list=incoming[name];next[name]=mergeImportedRecords(Array.isArray(db[name])?db[name]:[],list,item=>name==='clients'?(item.publicId?`publicId:${item.publicId}`:mergeKey(item)):mergeKey(item))}
