$('#cashPaymentForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),x=db.cashEntries.find(v=>v.id===f.get('entryId'));if(!x)return;const amount=Number(f.get('amount'))||0,remaining=cashOutstanding(x);if(amount<=0||amount>remaining+0.005){toast('O valor precisa ser maior que zero e não pode ultrapassar o saldo restante.');return}x.payments=Array.isArray(x.payments)?x.payments:[];if(!x.payments.length&&cashPaidAmount(x)>0){const prior=cashPaidAmount(x);x.payments.push({id:newId(),amount:prior,date:x.settledAt||x.date,method:x.payment||'Pagamento anterior',legacy:true})}x.payments.push({id:newId(),amount,date:String(f.get('date')),method:String(f.get('method')||''),created:new Date().toISOString()});const paid=cashPaidAmount(x);x.status=cashOutstanding(x)<=.005?(x.type==='entrada'?'recebido':'pago'):'parcial';x.settledAt=cashIsSettled(x)?String(f.get('date')):'';x.payment=String(f.get('method')||x.payment||'');x.updated=new Date().toISOString();if(x.quoteId){const q=db.quotes.find(v=>v.id===x.quoteId);if(q){q.receivedValue=cashPaidAmount(x);q.status=cashIsSettled(x)?'fechado':'aprovado';q.closedAt=cashIsSettled(x)?String(f.get('date')):'';q.paymentMethod=x.payment}}$('#cashPaymentDialog').close();persist();toast(cashIsSettled(x)?'Saldo quitado.':'Pagamento parcial registrado; saldo atualizado.')});
function cashReportEntries(){const year=$('#cashYear').value,month=$('#cashMonth').value,from=$('#cashFrom').value,to=$('#cashTo').value,client=$('#cashClientFilter').value,order=$('#cashOrderFilter').value;return db.cashEntries.filter(x=>(cashPaidInSelectedPeriod(x)>0||cashDueInSelectedPeriod(x)>0)&&(!client||(x.client||x.clientId)===client)&&(!order||x.serviceOrderId===order))}
function cashExportRows(){return cashReportEntries().map(x=>{const client=db.clients.find(c=>c.id===(x.client||x.clientId)),order=db.serviceOrders.find(o=>o.id===x.serviceOrderId);return [x.date,x.dueDate,x.description,x.category,client?.name||x.clientName||'',order?.number||'',x.type,cashPaidAmount(x)>0&&cashOutstanding(x)>0?'Parcial':cashIsSettled(x)?'Pago/recebido':'Pendente',Number(x.amount)||0,cashPaidInSelectedPeriod(x),cashDueInSelectedPeriod(x),x.payment||'']})}
const csvValue=v=>'"'+String(v??'').replaceAll('"','""')+'"';$('#cashExportCsv').addEventListener('click',()=>{const rows=[['Data','Vencimento','Descrição','Categoria','Cliente','OS','Tipo','Status','Valor total','Pago','Saldo','Forma de pagamento'],...cashExportRows()],csv='\uFEFF'+rows.map(row=>row.map(csvValue).join(';')).join('\r\n');download('santory-financeiro-'+$('#cashYear').value+'-'+$('#cashMonth').value+'.csv',csv,'text/csv;charset=utf-8');toast('Relatório financeiro exportado.')});
$('#cashExportPdf').addEventListener('click',()=>{const rows=cashExportRows(),period=$('#cashMonth').value==='all'?$('#cashYear').value:monthLabels[Number($('#cashMonth').value)-1]+' / '+$('#cashYear').value,paidIn=rows.filter(r=>r[6]==='entrada').reduce((n,r)=>n+r[9],0),paidOut=rows.filter(r=>r[6]==='saida').reduce((n,r)=>n+r[9],0),pending=rows.reduce((n,r)=>n+r[10],0),w=window.open('','_blank');if(!w){toast('Permita abrir uma nova janela para gerar o PDF.');return}w.document.write('<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Fechamento financeiro '+period+'</title><style>body{font:13px Arial,sans-serif;color:#17384a;margin:30px}h1{font-size:22px}p{color:#506c7a}.summary{display:flex;gap:20px;margin:20px 0}.summary div{padding:12px;border:1px solid #ccdadd;border-radius:8px}table{width:100%;border-collapse:collapse}th,td{padding:8px;border-bottom:1px solid #d9e3e6;text-align:left}th{background:#edf4f5;font-size:10px}td{font-size:11px}.right{text-align:right}@media print{button{display:none}}</style><h1>Fechamento financeiro · Santory Tec</h1><p>Período: '+esc(period)+' · Gerado em '+dateText(localISODate())+'</p><div class="summary"><div>Recebido<br><b>'+fmt(paidIn)+'</b></div><div>Pago<br><b>'+fmt(paidOut)+'</b></div><div>Resultado líquido<br><b>'+fmt(paidIn-paidOut)+'</b></div><div>Saldo pendente<br><b>'+fmt(pending)+'</b></div></div><table><thead><tr><th>Data / vencimento</th><th>Descrição</th><th>Cliente</th><th>Status</th><th class="right">Valor</th><th class="right">Pago</th><th class="right">Saldo</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+dateText(r[0])+' / '+dateText(r[1])+'</td><td>'+esc(r[2])+'</td><td>'+esc(r[4])+'</td><td>'+esc(r[7])+'</td><td class="right">'+fmt(r[8])+'</td><td class="right">'+fmt(r[9])+'</td><td class="right">'+fmt(r[10])+'</td></tr>').join('')+'</tbody></table><script>window.onload=()=>window.print()<\/script></html>');w.document.close()});
